/* WHAT IS DRAWN IS WHAT THE BOARD MEETS (orgo-u-62's condition, 10-16: a prop inside the fence is one mesh, drawn and collided, within a
 * centimetre — here exactly): the props GLB the view draws, read as the game reads it, against the collision data the sim builds from
 * (parks/<park>_props.js, generated by tools/props_col.mjs): every position bit for bit, every index; and each placed prop's triangles in
 * the built world's collision, placed by the one transform (sim/props.js). Usage: node tests/props.mjs <park module> [--plant moved] */
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { World } from '../build/js/sim/world.js';
import { propPoint } from '../build/js/sim/props.js';
const def = (await import(pathToFileURL(path.resolve(process.argv[2])).href)).default, P = def.PARK, plant = process.argv.includes('--plant');
let fail = 0; const ok = (c, m) => { console.log((c ? '✔ ' : '✖ ') + m); if (!c) fail++; };
const buf = fs.readFileSync(path.resolve('build', P.propsFile)), jl = buf.readUInt32LE(12), J = JSON.parse(buf.slice(20, 20 + jl).toString('utf8')), bin = buf.slice(20 + jl + 8);
const acc = (i) => { const a = J.accessors[i], v = J.bufferViews[a.bufferView], n = { SCALAR: 1, VEC2: 2, VEC3: 3 }[a.type], C = { 5126: Float32Array, 5125: Uint32Array, 5123: Uint16Array, 5121: Uint8Array }[a.componentType];
  return new C(bin.buffer, bin.byteOffset + (v.byteOffset || 0) + (a.byteOffset || 0), a.count * n); };
/* 1. the GLB's meshes = the collision data, bit for bit */
for (const nd of J.nodes) {
  if (nd.mesh == null) continue; const kind = nd.name.replace(/^prop_/, '').replace(/\.\d+$/, ''), M = P.propMeshes[kind]; if (!M) { ok(false, kind + ': in the GLB, not in the collision data'); continue; }
  const pos = [], idx = []; for (const pr of J.meshes[nd.mesh].primitives) { const p = acc(pr.attributes.POSITION), I = acc(pr.indices), base = pos.length / 3; for (const v of p) pos.push(v); for (const k of I) idx.push(base + k); }
  if (plant && kind === Object.keys(P.propMeshes)[0]) pos[0] += 0.01;   // the plant: one vertex of the drawn mesh 1 cm off
  const samePos = pos.length === M.pos.length && pos.every((v, k) => Object.is(Math.fround(v), M.pos[k])), sameIdx = idx.length === M.idx.length && idx.every((v, k) => v === M.idx[k]);
  ok(samePos && sameIdx, `${kind}: the drawn mesh is the collision mesh — ${M.pos.length / 3} vertices ${samePos ? 'bit for bit' : 'DIFFER'}, ${M.idx.length / 3} triangles ${sameIdx ? 'the same' : 'DIFFER'}`);
}
/* 2. each placed prop's triangles are in the built world, where the one transform puts them */
const w = new World(P, def.TREES), col = w.bvh, C = buildCol(P);
function buildCol(park) { let n = 0; for (const r of park.props) n += park.propMeshes[r.kind].idx.length / 3; return n; }
let found = 0, missing = [];
for (const r of P.props) {
  const M = P.propMeshes[r.kind];
  /* a ray straight down onto the middle of the prop's highest upward face must land on it (within 2 mm of its height) */
  let best = null;
  for (let t = 0; t < M.idx.length; t += 3) {
    const v = [0, 1, 2].map((k) => [M.pos[M.idx[t + k] * 3], M.pos[M.idx[t + k] * 3 + 1], M.pos[M.idx[t + k] * 3 + 2]]);
    const e1 = v[1].map((x, i) => x - v[0][i]), e2 = v[2].map((x, i) => x - v[0][i]), ny = e1[2] * e2[0] - e1[0] * e2[2], l = Math.hypot(e1[1] * e2[2] - e1[2] * e2[1], ny, e1[0] * e2[1] - e1[1] * e2[0]);
    const c = [0, 1, 2].map((i) => (v[0][i] + v[1][i] + v[2][i]) / 3);
    if (l > 1e-6 && ny / l > 0.9 && l / 2 > 1e-4 && (!best || c[1] > best[1])) best = c;
  }
  const q = propPoint(r, best[0], best[1], best[2]), h = col.raycast([q[0], q[1] + 1, q[2]], [0, -1, 0], 3);
  if (h && Math.abs(h.point[1] - q[1]) < 0.002) found++; else missing.push(`${r.kind} at ${r.at.join(',')} (${h ? 'met at ' + h.point[1].toFixed(3) : 'nothing'} for ${q[1].toFixed(3)})`);
}
ok(missing.length === 0, `every prop stands where it is drawn: ${found} of ${P.props.length} met at their highest point by a ray from above${missing.length ? ' — ' + missing.join('; ') : ''} (${C} prop triangles in the collision)`);
console.log(fail ? 'PROPS: RED' : 'PROPS: GREEN'); process.exit(fail ? 1 : 0);
